#pragma once

#include <stdbool.h>
#include <stdint.h>

#include "esp_err.h"

/*
 * NEMA 17 pan axis driven through a step/direction driver.
 *
 * Step pulses are generated by an LEDC timer, so commanding a rate costs one
 * register write and the pulse train itself costs no CPU time at all. The
 * trade-off is that the hardware does not report how many pulses it emitted;
 * stepper_driver_position_steps() integrates the commanded rate instead and is
 * therefore an estimate, accurate enough for soft limits but not a substitute
 * for a real encoder.
 */
esp_err_t stepper_driver_init(void);

/* Energise or de-energise the coils. */
void stepper_driver_set_enabled(bool enabled);
bool stepper_driver_is_enabled(void);

/*
 * Command a signed step rate in steps/s. Positive is the driver's forward
 * direction. Magnitudes below GIMBAL_PAN_MIN_STEP_RATE stop the axis. The
 * position estimate integrates the rate over real time, so it keeps up with the
 * pulses emitted however irregularly this is called.
 */
void stepper_driver_set_rate(float steps_per_second);

float stepper_driver_rate(void);

/* Estimated position from home, in microsteps, as of the last rate change.
 * Call from the gimbal task only; other tasks read the copy it publishes. */
int32_t stepper_driver_position_steps(void);

/* Estimated position at now_us, including the pulses emitted since the last
 * rate change. Same task restriction. */
float stepper_driver_position_at(int64_t now_us);

/* Treat the current position as home (zero) for the soft limits. */
void stepper_driver_zero_position(void);
